import { nanoid } from '@reduxjs/toolkit';

import { normalizeEffects } from 'app/services/EffectsService/settings';
import { TIME_SIGNATURES } from 'app/services/MelodiesService/meter';
import { MAX_TEMPO, MIN_TEMPO } from 'app/services/MelodiesService/tempo';

import { DrumBeat } from './beatLibrary';
import { MAX_STEPS, normalizeDrumState } from './patterns';
import {
  CustomDrumSample,
  MAX_SAMPLE_BYTES,
  isDrumSample,
  readCustomSample,
} from './samples';
import { decodeDrumClip } from './voices';

const format = 'melody-generator.drum-beat';
const maxFileBytes = 64 * 1024 * 1024;
const oversized = 'Beat files must be 64 MB or smaller.';
const invalid = 'Choose a valid beat file downloaded from Drum Machine.';

const customSamplesIn = (beat: DrumBeat) =>
  new Map(
    beat.state.tracks.flatMap(track => {
      const sample = beat.state.samples[track];
      return sample.kind === 'custom' ? [[sample.id, sample] as const] : [];
    }),
  );

const toBase64 = async (blob: Blob) => {
  const bytes = new Uint8Array(await blob.arrayBuffer());
  const chunks: string[] = [];
  for (let i = 0; i < bytes.length; i += 8192) {
    chunks.push(
      String.fromCharCode(...Array.from(bytes.subarray(i, i + 8192))),
    );
  }
  return btoa(chunks.join(''));
};

export const createBeatFile = async (beat: DrumBeat) => {
  let encodedSize = 0;
  const audio: [string, string][] = [];
  for (const id of Array.from(customSamplesIn(beat).keys())) {
    const blob = await readCustomSample(id);
    encodedSize += Math.ceil(blob.size / 3) * 4;
    if (encodedSize > maxFileBytes) throw new Error(oversized);
    audio.push([id, await toBase64(blob)]);
  }
  const file = new Blob(
    [
      JSON.stringify({
        format,
        version: 1,
        beat,
        audio: Object.fromEntries(audio),
      }),
    ],
    { type: 'application/json' },
  );
  if (file.size > maxFileBytes) throw new Error(oversized);
  return file;
};

export const readBeatFile = async (file: File) => {
  if (file.size > maxFileBytes) throw new Error(oversized);
  let data: {
    format?: unknown;
    version?: unknown;
    beat?: DrumBeat;
    audio?: Record<string, unknown>;
  };
  try {
    data = JSON.parse(await file.text());
  } catch {
    throw new Error(invalid);
  }
  if (data?.format !== format) throw new Error(invalid);
  if (data.version !== 1)
    throw new Error('This beat file uses an unsupported version.');
  const { beat, audio } = data;
  if (
    !beat ||
    !Array.isArray(beat.state?.tracks) ||
    !Number.isInteger(beat.bpm) ||
    beat.bpm < MIN_TEMPO ||
    beat.bpm > MAX_TEMPO ||
    !TIME_SIGNATURES.includes(beat.timeSignature) ||
    !beat.effects ||
    typeof beat.effects !== 'object' ||
    typeof beat.state.volume !== 'number' ||
    beat.state.volume < 0 ||
    beat.state.volume > 1
  )
    throw new Error(invalid);

  const state = normalizeDrumState(beat.state);
  if (
    state.tracks.length !== beat.state.tracks.length ||
    state.tracks.some((id, i) => {
      const row = beat.state.pattern?.[id];
      return (
        id !== beat.state.tracks[i] ||
        !isDrumSample(beat.state.samples?.[id]) ||
        typeof beat.state.muted?.[id] !== 'boolean' ||
        !Array.isArray(row) ||
        row.length !== MAX_STEPS ||
        row.some(step => typeof step !== 'boolean')
      );
    })
  )
    throw new Error(invalid);

  const clips: { sample: CustomDrumSample; blob: Blob }[] = [];
  const replacements = new Map<string, CustomDrumSample>();
  let decoder: OfflineAudioContext | undefined;
  for (const [id, sample] of Array.from(customSamplesIn(beat))) {
    const encoded =
      audio && Object.prototype.hasOwnProperty.call(audio, id)
        ? audio[id]
        : undefined;
    if (
      typeof encoded !== 'string' ||
      !encoded ||
      encoded.length > Math.ceil(MAX_SAMPLE_BYTES / 3) * 4
    ) {
      throw new Error('A custom sample is missing or too large.');
    }
    let bytes: Uint8Array;
    try {
      bytes = Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
    } catch {
      throw new Error('A custom sample in this beat is damaged.');
    }
    if (!bytes.length || bytes.length > MAX_SAMPLE_BYTES)
      throw new Error('A custom sample is empty or too large.');
    if (!window.OfflineAudioContext)
      throw new Error('This browser cannot import beats with custom samples.');
    decoder ??= new OfflineAudioContext(1, 1, 44100);
    const blob = new Blob([bytes]);
    await decodeDrumClip(decoder, sample, blob);
    const imported = { ...sample, id: `custom:${nanoid()}` };
    clips.push({ sample: imported, blob });
    replacements.set(id, imported);
  }
  state.tracks.forEach(id => {
    const sample = state.samples[id];
    if (sample.kind === 'custom')
      state.samples[id] = replacements.get(sample.id)!;
  });
  return {
    beat: {
      state,
      bpm: beat.bpm,
      timeSignature: beat.timeSignature,
      effects: normalizeEffects('drums', beat.effects),
    },
    clips,
  };
};
